 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();private static long V(JsonElement x)=>x.GetProperty("version").GetInt64();private static JsonElement E(object x)=>JsonSerializer.SerializeToElement(x,ApiJson.Options);
 private sealed record People(Guid Customer,Guid Branch,string Sales,string Peer,string Office,Guid Membership);
 private async Task<People> SetupPeople(HttpClient c)
 {var customer=await Create(c,"/customers",new CustomerDraft(Code(),"C05 client",null));var branch=await Create(c,$"/customers/{customer}/branches",new BranchMaintenance(Code(),"Sydney shop","10 Test Street","Sydney","NSW","2000"));var one=await Staff(db,"SALES");var peer=await Staff(db,"SALES");var office=await Staff(db,"OFFICE");foreach(var m in new[]{one.Membership,peer.Membership})await S("INSERT INTO identity.customer_assignments(company_id,membership_id,customer_id)VALUES(@c,@m,@customer)",("c",db.Company),("m",m),("customer",customer));return new(customer,branch,one.Subject,peer.Subject,office.Subject,one.Membership);}
 private static async Task<JsonElement> Make(HttpClient c,People p,string kind="NOTE",object? data=null,Guid? id=null,string? key=null)=>await Expect(await Send(c,HttpMethod.Post,"/crm/collaboration",new CollaborationCreate(id??Guid.NewGuid(),kind,p.Customer,p.Branch,E(data??new CustomerNote("Initial note"))),key:key),HttpStatusCode.Created);
 private static VisitPosition Position(DateTimeOffset? captured=null)=>new(-33.86m,151.21m,15,captured??DateTimeOffset.UtcNow.AddMinutes(-1));
 private static Task<HttpResponseMessage> Edit(HttpClient c,JsonElement o,object body,string? key=null)=>Send(c,HttpMethod.Put,$"/crm/collaboration/{Id(o)}",body,V(o),key);
 private static Task<HttpResponseMessage> Act(HttpClient c,JsonElement o,string action,object? body=null,string? key=null)=>Send(c,HttpMethod.Post,$"/crm/collaboration/{Id(o)}/{action}",body,V(o),key);
 private static async Task<Guid> Device(HttpClient c){var id=Guid.NewGuid();await Expect(await Send(c,HttpMethod.Post,"/crm/mobile/devices",new MobileDevice(id)),HttpStatusCode.Created);return id;}
 private static Task<HttpResponseMessage> Push(HttpClient c,Guid device,CollaborationOperation x,string? key=null)=>Send(c,HttpMethod.Post,$"/crm/mobile/devices/{device}/collaboration-operations",x,key:key);
 [Theory][InlineData("TEAM",true,true)][InlineData("PRIVATE",false,false)][InlineData("OFFICE",false,true)]
 public async Task Note_visibility_filters_list_detail_and_history(string visibility,bool peerRead,bool officeRead)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await SetupPeople(c);using var sales=api.Authenticated(p.Sales);using var peer=api.Authenticated(p.Peer);using var office=api.Authenticated(p.Office);var o=await Make(sales,p,data:new CustomerNote("Scoped note",visibility));await Expect(await Send(peer,HttpMethod.Get,$"/crm/collaboration/{Id(o)}"),peerRead?HttpStatusCode.OK:HttpStatusCode.Forbidden);await Expect(await Send(office,HttpMethod.Get,$"/crm/collaboration/{Id(o)}/history"),officeRead?HttpStatusCode.OK:HttpStatusCode.Forbidden);Assert.Equal(peerRead?1:0,(await Get(peer,"/crm/collaboration?kind=NOTE")).GetProperty("items").GetArrayLength());}
 [Fact]public async Task Notes_versions_history_and_office_corrections_are_preserved()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await SetupPeople(c);using var sales=api.Authenticated(p.Sales);using var office=api.Authenticated(p.Office);var o=await Make(sales,p);o=await Expect(await Edit(office,o,new CustomerNote("Office correction")),HttpStatusCode.OK);Assert.Equal(2,V(o));var history=await Get(sales,$"/crm/collaboration/{Id(o)}/history");Assert.Equal(2,history.GetArrayLength());Assert.Equal("Initial note",history[0].GetProperty("snapshot").GetProperty("data").GetProperty("text").GetString());Assert.Equal("Office correction",history[1].GetProperty("snapshot").GetProperty("data").GetProperty("text").GetString());}
 [Fact]public async Task Privacy_change_invalidates_peer_cursor_and_hides_old_body_after_reset()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await SetupPeople(c);using var sales=api.Authenticated(p.Sales);using var peer=api.Authenticated(p.Peer);var o=await Make(sales,p);var device=await Device(peer);var old=await Get(peer,$"/crm/mobile/devices/{device}/changes?after=0");Assert.Single(old.GetProperty("items").EnumerateArray(),x=>x.GetProperty("entityType").GetString()=="NOTE");await Expect(await Edit(sales,o,new CustomerNote("Secret revision","PRIVATE")),HttpStatusCode.OK);await Expect(await Send(peer,HttpMethod.Get,$"/crm/mobile/devices/{device}/changes?after={old.GetProperty("nextSequence").GetInt64()}&auth={old.GetProperty("auth").GetString()}"),HttpStatusCode.Conflict);var fresh=await Get(peer,$"/crm/mobile/devices/{device}/changes?after=0");Assert.DoesNotContain(fresh.GetProperty("items").EnumerateArray(),x=>x.GetProperty("entityType").GetString()=="NOTE");Assert.DoesNotContain("Secret",fresh.GetRawText());}
