 [Fact]public async Task Checkin_checkout_records_device_and_server_times_and_remains_visible_to_office_only()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await SetupPeople(c);using var sales=api.Authenticated(p.Sales);using var peer=api.Authenticated(p.Peer);using var office=api.Authenticated(p.Office);var o=await Make(sales,p,"VISIT",new VisitCheckIn(Position(),"Discuss samples"));Assert.True(o.GetProperty("data").TryGetProperty("checkInReceivedAt",out _));await Expect(await Send(peer,HttpMethod.Get,$"/crm/collaboration/{Id(o)}"),HttpStatusCode.Forbidden);await Expect(await Act(office,o,"checkout",new VisitCheckOut(Position())),HttpStatusCode.Forbidden);o=await Expect(await Act(sales,o,"checkout",new VisitCheckOut(Position(DateTimeOffset.UtcNow),"Done")),HttpStatusCode.OK);Assert.Equal("CLOSED",o.GetProperty("state").GetString());Assert.True(o.GetProperty("data").TryGetProperty("checkOutReceivedAt",out _));Assert.Single((await Get(office,"/crm/collaboration?kind=VISIT&state=CLOSED")).GetProperty("items").EnumerateArray());await Expect(await Send(sales,HttpMethod.Delete,$"/crm/collaboration/{Id(o)}",version:V(o)),HttpStatusCode.Conflict);}
