 [Theory][InlineData("create")][InlineData("update")][InlineData("checkout")][InlineData("push")]
 public async Task Late_audit_failure_rolls_back_object_history_feed_and_device_operation_then_same_key_retries(string action)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await SetupPeople(c);using var sales=api.Authenticated(p.Sales);JsonElement o=default;Guid device=Guid.Empty;if(action is"update"or"checkout")o=await Make(sales,p,action=="checkout"?"VISIT":"NOTE",action=="checkout"?new VisitCheckIn(Position()):new CustomerNote("Original"));if(action=="push")device=await Device(sales);var key=Code();var input=new CollaborationCreate(Guid.NewGuid(),"NOTE",p.Customer,p.Branch,E(new CustomerNote("Atomic")));var op=new CollaborationOperation(Guid.NewGuid(),1,input.Id,"CREATE","NOTE",p.Customer,p.Branch,Data:input.Data);var checkout=new VisitCheckOut(Position(DateTimeOffset.UtcNow));Task<HttpResponseMessage> Run()=>action switch{"create"=>Send(sales,HttpMethod.Post,"/crm/collaboration",input,key:key),"update"=>Edit(sales,o,new CustomerNote("Updated"),key),"checkout"=>Act(sales,o,"checkout",checkout,key),_=>Push(sales,device,op,key)};var before=await S("SELECT count(*)FROM crm.collaboration_changes WHERE company_id=@c",("c",db.Company));await S($"CREATE FUNCTION crm.test_c05_fail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='crm.collaboration_{action}'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c05_fail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION crm.test_c05_fail()");try{await Expect(await Run(),HttpStatusCode.UnprocessableEntity);Assert.Equal(before,await S("SELECT count(*)FROM crm.collaboration_changes WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM crm.mobile_operations WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER test_c05_fail ON platform.audit_events;DROP FUNCTION crm.test_c05_fail()");}await Expect(await Run(),action=="create"?HttpStatusCode.Created:HttpStatusCode.OK);}

